"use strict";
// Original human-authored reference, NOT generated by Luna or Ollama.
// The local builder replaces this file only inside a separate, review-required run.
function updateGame(state, input, dt) {
  if (state.status !== "playing" || !(dt > 0 && dt < 0.1)) return state;
  const player = state.player;
  const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, n));
  const overlap = (a, b) => a.x < b.x + b.w && a.x + a.w > b.x &&
                             a.y < b.y + b.h && a.y + a.h > b.y;
  player.vx = (Number(!!input.right) - Number(!!input.left)) * 265;
  if (input.jump && player.grounded) {
    player.vy = -655;
    player.grounded = false;
  }
  const previousBottom = player.y + player.h;
  player.x = clamp(player.x + player.vx * dt, 0, state.width - player.w);
  player.vy = clamp(player.vy + 1550 * dt, -900, 900);
  player.y += player.vy * dt;
  player.grounded = false;
  // One-way platforms: landing only while falling across the top.
  for (const p of state.platforms) {
    if (player.vy >= 0 && player.x + player.w > p.x + 5 && player.x < p.x + p.w - 5 &&
        previousBottom <= p.y + 6 && player.y + player.h >= p.y) {
      player.y = p.y - player.h;
      player.vy = 0;
      player.grounded = true;
    }
  }
  if (player.y + player.h >= state.floor) {
    player.y = state.floor - player.h;
    player.vy = 0;
    player.grounded = true;
  }
  player.hurtTime = Math.max(0, player.hurtTime - dt);
  for (const enemy of state.enemies) {
    enemy.x += enemy.direction * enemy.speed * dt;
    if (enemy.x < enemy.left) { enemy.x = enemy.left; enemy.direction = 1; }
    if (enemy.x > enemy.right) { enemy.x = enemy.right; enemy.direction = -1; }
    if (overlap(player, enemy) && player.hurtTime <= 0) {
      player.hp = Math.max(0, player.hp - 1);
      player.hurtTime = 1.15;
      player.vy = -320;
      player.x = clamp(player.x + (player.x < enemy.x ? -38 : 38), 0, state.width - player.w);
    }
  }
  for (const star of state.stars) {
    const px = player.x + player.w / 2;
    const py = player.y + player.h / 2;
    if (!star.taken && Math.hypot(px - star.x, py - star.y) < 37) star.taken = true;
  }
  if (player.hp <= 0) state.status = "lost";
  else if (state.stars.every(s => s.taken) && player.x + player.w >= state.exitX) {
    state.status = "won";
  }
  return state;
}
